{
  "date": "2026-09-30",
  "title": "The camera count is not the fire count",
  "topic": "SPS smoke-camera workflow and the installed-versus-detected reporting gap.",
  "beat": "weather-and-emergency",
  "entities": [
    "Southwestern Public Service",
    "Xcel Energy",
    "Pano AI"
  ],
  "runtime_s": 44,
  "credits_s": 5,
  "credits": "TEXAS AI DOCKET\nSOURCES\nSPS annual resiliency report\nPUCT approval order\nXcel Energy program description\nILLUSTRATION\nOriginal source-grounded geometry\nMUSIC\nMUSIC\n\"Echoes of Time v2\" by Kevin MacLeod (incompetech.com) - licensed under CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/) - trimmed and synced to picture",
  "derived_from": "scratch",
  "divergence_note": "This film follows a physical smoke signal into a camera and then contrasts equipment with detections. It leaves the prior documentary source-page treatment behind through a horizon, optical object and paired reporting categories with a concrete unresolved ending.",
  "fingerprint": {
    "pov": "horizon-to-optical mechanism",
    "motion_vector": "rising smoke into camera review",
    "hero_treatment": "tactile camera and conserved smoke image",
    "layout": "horizon depth into paired measurement records",
    "register": "source-grounded intended-workflow illustration",
    "camera_strategy": "riseWith",
    "light_story": "noon-hard",
    "palette": "caliche ochre, smoke grey, ivory and dark iron",
    "metaphor": "a camera body cannot become a detected-fire count"
  },
  "fauna_scope": {
    "status": "none",
    "reason": "No animal contributes to the verified smoke camera workflow."
  },
  "cinematic_template": "smoke-camera-v1",
  "native_media": [],
  "visual_research": {
    "searches": [
      {
        "query": "site.dsv.com Skyways September 2026 drone offshore",
        "finding": "No authenticated current DSV operation footage established. Search results described announced Norden fall deployment; no current Texas cargo imagery established."
      },
      {
        "query": "site.skyways.com offshore wind cargo drop images video media rights",
        "finding": "Located Skyways offshore press imagery and GlobeNewswire attachment for older Arkona demonstration. German offshore operations cannot prove current Texas action."
      },
      {
        "query": "Xcel Energy Pano AI 97 cameras Texas September 2026 wildfire",
        "finding": "Located current Docket/Tribune testimony reporting and primary Xcel Panhandle release. No Texas-only97inventory or current incident film established."
      },
      {
        "query": "site.pano.ai Texas Xcel Energy cameras 2026 images wildfire",
        "finding": "Located official Pano news page, Texas2024 release lead and public Media Kit. Kit contained camera detail and Oregon tower still; no footage or explicit license file."
      }
    ],
    "candidates": [
      {
        "url": "https://pano-la.b-cdn.net/Pano_Media%20Kit.zip",
        "file": "out/dispatch/sources/pano-camera.png",
        "decision": "reject",
        "reason": "Actual pixels show suspended white housing and black pan/tilt lens. Useful morphology; no Texas site, smoke or detection. Public media kit supplies provenance without explicit reuse license."
      },
      {
        "url": "https://pano-la.b-cdn.net/Pano_Media%20Kit.zip",
        "file": "out/dispatch/sources/pano-oregon.jpg",
        "decision": "reject",
        "reason": "Inspected lattice tower with two hanging cameras above conifer forest; filename locates Oregon. Cannot establish Texas Panhandle."
      },
      {
        "url": "https://newsroom.xcelenergy.com/multimedia/gallery",
        "decision": "reject",
        "reason": "Fetched gallery requires request and signed-in profile. No footage inspected or rights obtained."
      },
      {
        "url": "https://www.globenewswire.com/NewsRoom/AttachmentNg/c73f7c2f-8376-4ad9-8442-d68627929ec6",
        "decision": "reject",
        "reason": "Search lead for older German Arkona demonstration. No actual pixels inspected; cannot depict current Texas operation."
      }
    ],
    "decision": "Use original source-grounded illustration; public kit imagery serves morphology reference only. No prior photographic asset or unavailable footage enters film.",
    "query_count": 4,
    "actual_pixel_inspections": 2,
    "access_inspections": 2,
    "new_research_performed": false
  },
  "captions": [
    {
      "id": "c1",
      "start": 1.26,
      "end": 2.74,
      "text": "Smoke is the signal.",
      "source": "measured_boundary"
    },
    {
      "id": "c2",
      "start": 3.32,
      "end": 4.92,
      "text": "A camera is only the start.",
      "source": "measured_boundary"
    },
    {
      "id": "c3",
      "start": 5.82,
      "end": 7.16,
      "text": "In the Texas Panhandle,",
      "source": "measured_boundary"
    },
    {
      "id": "c4",
      "start": 7.46,
      "end": 12.4,
      "text": "Southwestern Public Service says its AI cameras are meant to identify fires.",
      "source": "measured_boundary"
    },
    {
      "id": "c5",
      "start": 12.8,
      "end": 14.56,
      "text": "Then notify a command center.",
      "source": "measured_boundary"
    },
    {
      "id": "c6",
      "start": 15.28,
      "end": 18.28,
      "text": "The commission asked for a count of fire detections.",
      "source": "measured_boundary"
    },
    {
      "id": "c7",
      "start": 18.98,
      "end": 22.22,
      "text": "The utility's May report, covering part of last year,",
      "source": "measured_boundary"
    },
    {
      "id": "c8",
      "start": 22.38,
      "end": 25.34,
      "text": "instead lists thirty-three cameras installed.",
      "source": "measured_boundary"
    },
    {
      "id": "c9",
      "start": 26.06,
      "end": 28.44,
      "text": "Installed cameras are a different measurement.",
      "source": "measured_boundary"
    },
    {
      "id": "c10",
      "start": 29.36,
      "end": 33.66,
      "text": "A camera can watch the horizon while crews need a usable warning.",
      "source": "measured_boundary"
    },
    {
      "id": "c11",
      "start": 34.54,
      "end": 38.4,
      "text": "A reader can ask for the fire-detection count missing from this report.",
      "source": "measured_boundary"
    },
    {
      "id": "c12",
      "start": 39.18,
      "end": 40.3,
      "text": "The hardware is counted.",
      "source": "measured_boundary"
    },
    {
      "id": "c13",
      "start": 41.0,
      "end": 43.3,
      "text": "The detection count is missing from this report.",
      "source": "measured_boundary"
    }
  ],
